INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist DML dasselbe wie DDL?', 2, '[{"text": "Nein", "correct": true, "because": "DML manipuliert Daten, DDL definiert Struktur"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Zwecke"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit DML?', 3, '[{"text": "Daten ändern", "correct": true, "because": "Fügt ein, aktualisiert, löscht"}, {"text": "Tabellen erstellen", "correct": false, "because": "DDL-Aufgabe"}, {"text": "Zugriffe steuern", "correct": false, "because": "DCL-Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Befehle gehören zur DML?', 5, '[{"text": "INSERT", "correct": true, "because": "Fügt Daten ein"}, {"text": "UPDATE", "correct": true, "because": "Ändert Daten"}, {"text": "CREATE", "correct": false, "because": "DDL-Befehl"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DML bearbeitet Daten. b) Es definiert Tabellenstrukturen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist DDL"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung von DML?', 4, '[{"text": "Syntax", "correct": false, "because": "Muss korrekt sein"}, {"text": "Datenintegrität", "correct": false, "because": "Schützt Konsistenz"}, {"text": "Monitorauflösung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DML Datenbankstrukturen ändert?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Daten, keine Struktur"}, {"text": "Ja", "correct": false, "because": "DDL-Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Befehl fügt Daten hinzu?', 3, '[{"text": "INSERT", "correct": true, "because": "Fügt neue Datensätze ein"}, {"text": "ALTER", "correct": false, "because": "Ändert Struktur"}, {"text": "GRANT", "correct": false, "because": "Vergibt Rechte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben übernimmt DML?', 5, '[{"text": "Daten einfügen", "correct": true, "because": "Neue Einträge"}, {"text": "Daten löschen", "correct": true, "because": "Entfernt Einträge"}, {"text": "Tabellen erstellen", "correct": false, "because": "DDL-Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) DML ist für Datenänderungen. b) Es verwaltet Benutzerrechte. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist DCL"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für DML?', 4, '[{"text": "Datenbankzugriff", "correct": false, "because": "Notwendig"}, {"text": "SQL-Kenntnisse", "correct": false, "because": "Für Befehle nötig"}, {"text": "Grafiktreiber", "correct": true, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist DML für Strukturänderungen?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Datenmanipulation"}, {"text": "Ja", "correct": false, "because": "DDL-Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Befehle ändern Daten?', 4, '[{"text": "UPDATE", "correct": true, "because": "Modifiziert Einträge"}, {"text": "DELETE", "correct": true, "because": "Entfernt Einträge"}, {"text": "DROP", "correct": false, "because": "DDL-Befehl"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass DML Datenbanken erstellt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Das macht DDL"}, {"text": "Ja", "correct": false, "because": "Nur Datenbearbeitung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei DML?', 3, '[{"text": "Datenintegrität", "correct": true, "because": "Sichert Konsistenz"}, {"text": "Schnelle Ausführung", "correct": false, "because": "Richtigkeit wichtiger"}, {"text": "Minimale Rechte", "correct": false, "because": "DCL-Thema"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DML ist Teil von SQL. b) Es definiert Schemata.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist DDL"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Operationen gehören zu DML?', 5, '[{"text": "Einfügen", "correct": true, "because": "Neue Daten"}, {"text": "Abfragen", "correct": true, "because": "Daten abrufen"}, {"text": "Tabellen ändern", "correct": false, "because": "DDL-Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Nutzung unwichtig?', 3, '[{"text": "WHERE-Bedingung", "correct": false, "because": "Präzisiert Änderungen"}, {"text": "Transaktionen", "correct": false, "because": "Sichert Konsistenz"}, {"text": "Tastaturtyp", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann DML Zugriffsrechte vergeben?', 3, '[{"text": "Nein", "correct": true, "because": "Das macht DCL"}, {"text": "Ja", "correct": false, "because": "Nur Datenbearbeitung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DML in allen Datenbanken gleich ist?', 2, '[{"text": "Nein", "correct": true, "because": "Syntax kann variieren"}, {"text": "Ja", "correct": false, "because": "DBMS-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt SELECT in DML?', 4, '[{"text": "Daten abrufen", "correct": true, "because": "Liest Datensätze"}, {"text": "Struktur ändern", "correct": false, "because": "DDL-Aufgabe"}, {"text": "Rechte vergeben", "correct": false, "because": "DCL-Funktion"}]');
